```python
from datetime import date, timedelta

def covered_days(ranges):
    ivs = []
    for r in ranges:
        a = date.fromisoformat(r['start'])
        b = date.fromisoformat(r['end'])
        if b < a:
            a, b = b, a
        ivs.append((a, b))
    if not ivs:
        return 0
    ivs.sort()
    merged = [list(ivs[0])]
    for s, e in ivs[1:]:
        if s <= merged[-1][1] + timedelta(days=1):
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    return sum((e - s).days + 1 for s, e in merged)

assert covered_days([
    {'start': '2024-01-01', 'end': '2024-01-03'},
    {'start': '2024-01-03', 'end': '2024-01-04'},
]) == 4
```

Adjacent days also merge (`+ timedelta(days=1)`) so Jan 1–2 plus Jan 3–3 is three days, not two islands.

